shell_commands:
cat > /tmp/test-ajv.js << 'EOF'
import {Ajv} from 'ajv';

const ajv = new Ajv({strict: false});
const schema = {
  type: 'object',
  properties: {ssn: {type: 'string'}},
  required: ['ssn'],
};

const validator = ajv.compile(schema);
const input = {ssn: 123456789};

validator(input);
console.log('Errors:', JSON.stringify(validator.errors, null, 2));
EOF
node /tmp/test-ajv.js

